 counts=[sum(p['metrics'][str(h)]['first_valid_hit'] is not None and p['metrics'][str(h)]['first_valid_hit']<=t for p in clean) for t in(5,11,23,39)];lines.append(f"| {h} | {' | '.join(map(str,counts))} | {len(clean)} |")
